import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class PublicExamplesTest{@Test void fourOperationsAndPublishedArray(){double[][]expected={{4,-2},{-2,6},{11,2},{-0.2,0.4}};for(int op=0;op<4;op++)assertArrayEquals(expected[op],TaskBinding.parts(TaskBinding.operation(TaskBinding.value(1,2),TaskBinding.value(3,-4),op)),1e-8);Object[]a=TaskBinding.array(TaskBinding.value(1,1),TaskBinding.value(1,-1));assertArrayEquals(new double[]{2,0},TaskBinding.parts(TaskBinding.sum(a)),1e-8);assertArrayEquals(new double[]{2,0},TaskBinding.parts(TaskBinding.product(a)),1e-8);}}
